import { GrainGradient } from "@paper-design/shaders-react";

/**
 * GradientBackground Component
 *
 * This component renders the underlying "Energy Field" for our Game of Life simulation.
 * It uses a WebGL fragment shader (GrainGradient) to create a high-quality, noisy,
 * shifting color landscape.
 *
 * THE VISUAL STACK:
 * 1. Bottom Layer: Only this GradientBackground. It fills the screen with color.
 * 2. Top Layer: The LifeSimulation canvas.
 *
 * The LifeSimulation canvas is mostly Opaque Black. It has small transparent "holes"
 * where the cells are alive. These holes reveal THIS gradient component underneath.
 * This creates the illusion that the cells are glowing with these colors.
 */
export function GradientBackground() {
  return (
    <div className="absolute inset-0">
      <GrainGradient
        colorBack="hsla(0, 0%, 0%, 1.00)"
        colors={[
          "hsl(14, 100%, 57%)", // Vibrant Orange
          "hsl(45, 100%, 51%)", // Golden Yellow
          "hsl(340, 82%, 52%)", // Deep Pink/Magenta
        ]} // Deep black base
        // Shader Parameters tuned for "Living" feel:
        intensity={1.2} // Harder edges than default for more defined "blobs"
        noise={0.1} // High intensity to punch through the small cell windows
        offsetX={0} // Subtle grain texture
        // Motion parameters
        offsetY={0} // Fast movement so the colors shift noticeably under stationary cells
        // The "Plasma" Palette
        rotation={0}
        // Unused parameters set to defaults
        scale={1}
        shape="corners"
        softness={0.5}
        speed={3}
        style={{ height: "100%", width: "100%" }}
      />
    </div>
  );
}

"use client";

import type React from "react";
import { useEffect, useRef, useState } from "react";
import { cn } from "@/lib/utils";

interface LifeSimulationProps {
  className?: string;
}

/**
 * CELL_SIZE defines the resolution of our "pixel art" simulation.
 * 8px gives a chunky, retro feel while being performant enough for large screens.
 * Smaller values (e.g., 4) would be sharper but more CPU intensive.
 */
const CELL_SIZE = 8;

/**
 * LifeSimulation Component
 *
 * This component renders the Game of Life simulation on top of the Gradient background.
 *
 * VISUAL TECHNIQUE: "Inverse Masking"
 * -----------------------------------
 * instead of drawing the cells as colored squares, we treat this canvas as a "Mask".
 * 1. The Canvas covers the entire screen.
 * 2. We fill the Canvas with OPAQUE BLACK. This hides the colorful gradient behind it.
 * 3. Where a cell is ALIVE, we clear the black pixel (make it TRANSPARENT).
 * 4. This reveals the gradient *through* the living cell window.
 *
 * This guarantees that the cells always perfectly match the complex, shifting colors
 * of the underlying shader, because they technically ARE the shader.
 */
export function LifeSimulation({ className }: LifeSimulationProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const workerRef = useRef<Worker>(null);

  // We store the calculated grid resolution here (Screen Size / CELL_SIZE)
  const [resolution, setResolution] = useState({ w: 0, h: 0 });

  /**
   * WORKER INITIALIZATION
   * We use a Web Worker to run the heavy simulation loop off the main thread.
   * This ensures the UI remains buttery smooth (60fps) even if the math gets heavy.
   */
  useEffect(() => {
    // Initialize the dedicated simulation worker
    workerRef.current = new Worker(
      new URL("./simulation.worker.ts", import.meta.url)
    );

    const handleResize = () => {
      if (!containerRef.current) {
        return;
      }
      const { clientWidth, clientHeight } = containerRef.current;

      // Calculate how many cells fit on screen
      const w = Math.ceil(clientWidth / CELL_SIZE);
      const h = Math.ceil(clientHeight / CELL_SIZE);

      setResolution({ w, h });

      // Tell the worker to resize its grid
      workerRef.current?.postMessage({
        type: "INIT",
        width: w,
        height: h,
      });
    };

    window.addEventListener("resize", handleResize);
    handleResize(); // Initial setup

    return () => {
      window.removeEventListener("resize", handleResize);
      workerRef.current?.terminate();
    };
  }, []);

  /**
   * RENDER LOOP
   * This loop receives grid data from the worker and paints it to the canvas.
   */
  useEffect(() => {
    if (!(canvasRef.current && workerRef.current) || resolution.w === 0) {
      return;
    }

    const canvas = canvasRef.current;
    // Optimization: explicit alpha: true is default, but good to be explicit for our masking trick
    const ctx = canvas.getContext("2d", { alpha: true });
    if (!ctx) {
      return;
    }

    // Set internal canvas resolution to match the simulation grid (e.g., 200x100)
    // CSS will scale this up to cover the full 1920x1080 screen
    canvas.width = resolution.w;
    canvas.height = resolution.h;

    // CRITICAL: Disable anti-aliasing to keep the pixels crisp and square
    ctx.imageSmoothingEnabled = false;

    let animateId: number;
    let lastGrid: Uint8Array | null = null;

    // Listen for updates from the Worker
    workerRef.current.onmessage = (e) => {
      if (e.data.type === "UPDATE") {
        // We just store the grid reference; we don't draw immediately.
        // We draw in the requestAnimationFrame loop to stay synced with screen refresh.
        lastGrid = e.data.grid;
      }
    };

    const render = () => {
      // 1. Kick off the math for the *next* frame immediately
      workerRef.current?.postMessage({ type: "TICK" });

      // 2. Draw the *current* frame if we have data
      if (lastGrid && ctx) {
        // Create a buffer to write pixel data directly (fastest method in JS)
        const imgData = ctx.createImageData(resolution.w, resolution.h);
        const data = imgData.data;

        for (let i = 0; i < lastGrid.length; i++) {
          const stride = i * 4;
          const val = lastGrid[i]; // Value is 0 (Dead) to 255 (Alive)

          /**
           * PIXEL SHADER LOGIC (The "Inverse Mask")
           *
           * We calculate Alpha (Transparency) based on the cell's "Life Value".
           *
           * - If val is 0 (Absolute Death), alpha is high. The pixel is black. Hides gradient.
           * - If val is 255 (Full Life), alpha is 0. The pixel is transparent. Reveals gradient.
           * - If val is 100 (Dying/Trailing), alpha is partial. Creates a dimming effect.
           *
           * The `0.5` factor means the "Darkness" is only 50% opaque max.
           * This allows the gradient to faintly shine through even the dead areas,
           * creating a unified atmospheric glow rather than pitch black void.
           */
          const alpha = (255 - val) * 0.5;

          data[stride] = 0; // R (Black)
          data[stride + 1] = 0; // G (Black)
          data[stride + 2] = 0; // B (Black)
          data[stride + 3] = alpha; // A (Opacity)
        }

        ctx.putImageData(imgData, 0, 0);
      }

      animateId = requestAnimationFrame(render);
    };

    render();

    return () => {
      cancelAnimationFrame(animateId);
    };
  }, [resolution]);

  // INTERACTION HANDLERS //////////////////////////////////////////////////

  // Draw life when mouse moves
  const handlePointerMove = (e: React.PointerEvent) => {
    if (!(containerRef.current && workerRef.current)) {
      return;
    }

    const rect = containerRef.current.getBoundingClientRect();
    // Convert screen coordinates to grid coordinates
    const x = Math.floor((e.clientX - rect.left) / CELL_SIZE);
    const y = Math.floor((e.clientY - rect.top) / CELL_SIZE);

    workerRef.current.postMessage({
      type: "SPLAT",
      x,
      y,
      radius: 3, // Brush size
    });
  };

  // Reset on click
  const handlePointerDown = () => {
    workerRef.current?.postMessage({ type: "RESET" });
  };

  return (
    <div
      className={cn("absolute inset-0 z-0", className)}
      onPointerDown={handlePointerDown}
      onPointerMove={handlePointerMove}
      ref={containerRef}
      // `pointerEvents: auto` enables the mouse interactions on this layer
      // `touchAction: none` prevents scrolling on mobile while painting life
      style={{ touchAction: "none", pointerEvents: "auto" }}
    >
      <canvas
        className="rendering-pixelated block h-full w-full"
        ref={canvasRef}
        style={{
          // Use 'normal' blending because we are manually handling the transparency
          // in the pixel loop above.
          mixBlendMode: "normal",
          // CSS property to keep the pixels chunky when scaled up
          imageRendering: "pixelated",
        }}
      />
    </div>
  );
}

export {};

/**
 * SIMULATION WORKER
 * -----------------
 * This Web Worker handles the mathematical core of the Game of Life.
 *
 * By running in a worker, we decouple the simulation tick rate from the main UI thread.
 * Even if the simulation becomes computationally heavy (e.g. valid large grids), the
 * user's scrolling and browser responsiveness remain unaffected.
 */

// Cell States
const ALIVE = 255; // A fully alive cell value
const DEAD = 0; // A fully dead cell value

/**
 * DECAY_RATE determines the length of the "Ghost Trails".
 *
 * In standard Conway's Game of Life, cells die instantly (1 -> 0).
 * Here, we use values 0-255. When a cell dies, we don't set it to 0,
 * we subtract this rate.
 *
 * Value 5 means trails last ~50 frames (255/5), which is nearly 1 second at 60fps.
 * This creates the smooth, comet-like tail effect behind gliders.
 */
const DECAY_RATE = 5;

// Message Types for Type Safety
type WorkerMessage =
  | { type: "INIT"; width: number; height: number }
  | { type: "TICK" }
  | { type: "SPLAT"; x: number; y: number; radius: number }
  | { type: "RESET" };

// Internal State
// We use Uint8Array for maximum memory efficiency and cache locality.
// It is significantly faster than standard JS arrays of objects.
let grid: Uint8Array; // The current state of the universe
let nextGrid: Uint8Array; // The "write buffer" for the next frame
let width = 0;
let height = 0;

/**
 * Initialize the grid memory buffers.
 */
function initGrid(w: number, h: number) {
  width = w;
  height = h;
  // We add +2 padding to the size (though simplified logic below doesn't use it yet)
  // to potentially allow for easier boundary checking optimizations in future.
  const size = (width + 2) * (height + 2);
  grid = new Uint8Array(size);
  nextGrid = new Uint8Array(size);

  randomize();
}

/**
 * Seed the universe with random chaos.
 */
function randomize() {
  for (let i = 0; i < grid.length; i++) {
    // 15% chance of a cell starting ALIVE
    grid[i] = Math.random() > 0.85 ? ALIVE : DEAD;
  }
}

/**
 * THE MAIN SIMULATION LOOP (TICK)
 * -------------------------------
 * This function computes the Next Generation of the universe based on Conway's 4 Rules.
 */
function tick() {
  if (!(grid && width)) {
    return;
  }

  const wReal = width;
  const hReal = height;

  // Optimized Loop traversing y then x for memory locality
  for (let y = 0; y < hReal; y++) {
    // COORDINATE WRAPPING (Toroidal Geometry)
    // We simulate a universe that wraps around edges (Pac-Man style).
    // If you exit the right side, you enter the left.
    // This preserves "energy" inside the system longer than hard walls.

    // Pre-calculating row offsets helps performance inside the inner loop
    const yUp = ((y - 1 + hReal) % hReal) * wReal;
    const ySame = y * wReal;
    const yDown = ((y + 1) % hReal) * wReal;

    for (let x = 0; x < wReal; x++) {
      const xLeft = (x - 1 + wReal) % wReal;
      const xRight = (x + 1) % wReal;

      // Count Living Neighbors (Moore Neighborhood)
      // Checks all 8 surrounding cells:
      // TL T TR
      //  L . R
      // BL B BR
      let neighbors = 0;

      // Top Row
      if (grid[yUp + xLeft] === ALIVE) {
        neighbors++;
      }
      if (grid[yUp + x] === ALIVE) {
        neighbors++;
      }
      if (grid[yUp + xRight] === ALIVE) {
        neighbors++;
      }

      // Middle Row (Left/Right)
      if (grid[ySame + xLeft] === ALIVE) {
        neighbors++;
      }
      if (grid[ySame + xRight] === ALIVE) {
        neighbors++;
      }

      // Bottom Row
      if (grid[yDown + xLeft] === ALIVE) {
        neighbors++;
      }
      if (grid[yDown + x] === ALIVE) {
        neighbors++;
      }
      if (grid[yDown + xRight] === ALIVE) {
        neighbors++;
      }

      const selfIndex = ySame + x;
      const selfVal = grid[selfIndex];

      // APPLY RULES:
      // 1. Survival: A live cell with 2 or 3 neighbors lives on.
      // 2. Birth: A dead cell with exactly 3 neighbors becomes alive.
      // 3. Death: Overpopulation (>3) or Loneliness (<2) kills the cell.
      // 4. Decay: (Custom Rule) Dead/Dying cells fade out slowly.

      if (selfVal === ALIVE) {
        if (neighbors === 2 || neighbors === 3) {
          nextGrid[selfIndex] = ALIVE;
        } else {
          // Rule 3: Death (start decaying)
          nextGrid[selfIndex] = Math.max(0, selfVal - DECAY_RATE);
        }
      } else if (neighbors === 3) {
        // Rule 2: Birth
        nextGrid[selfIndex] = ALIVE;
      } else {
        // Rule 4: Continue decaying if not fully dead
        nextGrid[selfIndex] = Math.max(0, selfVal - DECAY_RATE);
      }
    }
  }

  // "Double Buffering": Swap the arrays.
  // `nextGrid` becomes the current `grid` for the next frame.
  // `grid` becomes the scratchpad for the next calculation.
  // This is much faster than creating a new array every frame.
  const temp = grid;
  grid = nextGrid;
  nextGrid = temp;

  // Send the calculated frame back to the Main Thread/UI for rendering
  self.postMessage({ type: "UPDATE", grid });
}

/**
 * INTERACTION: SPLAT
 * Adds a splash of life at a specific coordinate (e.g., mouse cursor).
 */
function splat(centerX: number, centerY: number, radius: number) {
  if (!grid) {
    return;
  }

  // Add random life in a circular area
  const r2 = radius * radius;

  for (let y = -radius; y <= radius; y++) {
    for (let x = -radius; x <= radius; x++) {
      // Circle distance check
      if (x * x + y * y <= r2) {
        // Wrap coordinates logic
        const tX = (centerX + x + width) % width;
        const tY = (centerY + y + height) % height;

        // 50% chance to add life per pixel in the brush
        if (Math.random() > 0.5) {
          grid[tY * width + tX] = ALIVE;
        }
      }
    }
  }
}

// Global Event Listener for messages from the Main Thread
self.onmessage = (e: MessageEvent<WorkerMessage>) => {
  const { type } = e.data;

  switch (type) {
    case "INIT":
      initGrid(e.data.width, e.data.height);
      break;
    case "TICK":
      tick();
      break;
    case "SPLAT":
      splat(e.data.x, e.data.y, e.data.radius);
      break;
    case "RESET":
      randomize();
      break;
  }
};

"use client";

import Matter from "matter-js";
import Image from "next/image";
import type React from "react";
import { useEffect, useRef, useState } from "react";
import { usePhysics } from "./PhysicsContext";

interface DesktopIconProps {
  height?: number;
  iconSrc: string;
  label: string;
  onDoubleClick?: () => void;
  width?: number;
  x: number;
  y: number;
}

const DesktopIcon: React.FC<DesktopIconProps> = ({
  x,
  y,
  label,
  iconSrc,
  width = 64,
  height = 64,
  onDoubleClick,
}) => {
  const { engine, isReady } = usePhysics();
  const bodyRef = useRef<Matter.Body | null>(null);
  const elementRef = useRef<HTMLDivElement>(null);
  const [isSelected, setIsSelected] = useState(false);

  // Initialize Physics Body
  useEffect(() => {
    if (!(engine && isReady && elementRef.current)) {
      return;
    }

    // Create a rectangular body for the icon
    // High air friction to stop it from drifting endlessly (like "bumper cars" in fluid)
    const body = Matter.Bodies.rectangle(x, y, width + 20, height + 20, {
      frictionAir: 0.15, // Damping - stops relatively quickly after being hit
      restitution: 0.5, // Bounciness
      density: 0.001,
      label: `icon-${label}`,
    });

    bodyRef.current = body;
    Matter.World.add(engine.world, body);

    // Sync loop
    const updatePosition = () => {
      if (bodyRef.current && elementRef.current) {
        const { position, angle } = bodyRef.current;
        // Icons usually don't rotate in OS X, so we might lock rotation or keep it subtle
        // For "bumper cars", subtle rotation is fun.
        const degrees = angle * (180 / Math.PI);
        elementRef.current.style.transform = `translate(${position.x - (width + 40) / 2}px, ${position.y - (height + 20) / 2}px) rotate(${degrees}deg)`;
      }
    };

    Matter.Events.on(engine, "afterUpdate", updatePosition);

    return () => {
      if (engine && bodyRef.current) {
        Matter.World.remove(engine.world, bodyRef.current);
        Matter.Events.off(engine, "afterUpdate", updatePosition);
      }
    };
  }, [engine, isReady, height, label, width, x, y]); // Only run once on mount to set initial position

  return (
    <div
      className="group pointer-events-auto absolute top-0 left-0 flex select-none flex-col items-center justify-start"
      onClick={(e) => e.stopPropagation()}
      onDoubleClick={(e) => {
        e.stopPropagation();
        onDoubleClick?.();
      }}
      onMouseDown={() => {
        // Do NOT stop propagation. We want the event to bubble to the GravityDesktop container
        // so that Matter.MouseConstraint can detect the mouse down and initiate a physics drag.
        setIsSelected(true);
      }}
      ref={elementRef}
      style={{
        width: width + 40, // Click area
        willChange: "transform",
        // Position handled by transform
      }}
    >
      <div
        className={`relative mb-1 ${isSelected ? "brightness-[0.8]" : ""} pointer-events-none`}
        style={{ width, height }}
      >
        <Image
          alt={label}
          className="object-contain drop-shadow-md"
          draggable={false}
          height={height}
          src={iconSrc}
          width={width}
        />
      </div>

      {/* Label */}
      <div
        className={`pointer-events-none max-w-full break-words rounded-full px-2 py-[2px] text-center font-medium text-[12px] leading-tight ${
          isSelected
            ? "bg-[#3333cc] text-white"
            : "text-white drop-shadow-[0_1px_2px_rgba(0,0,0,0.8)]"
        }
                `}
        style={{ fontFamily: '"Lucida Grande", sans-serif' }}
      >
        {label}
      </div>
    </div>
  );
};

export default DesktopIcon;

"use client";

import Matter from "matter-js";
import type React from "react";
import { createContext, useContext, useEffect, useRef, useState } from "react";

interface PhysicsContextType {
  engine: Matter.Engine | null;
  isReady: boolean;
  world: Matter.World | null;
}

const PhysicsContext = createContext<PhysicsContextType>({
  engine: null,
  world: null,
  isReady: false,
});

export const usePhysics = () => useContext(PhysicsContext);

interface PhysicsProviderProps {
  children: React.ReactNode;
  debug?: boolean; // If true, renders the matter.js debug canvas
}

export const PhysicsProvider: React.FC<PhysicsProviderProps> = ({
  children,
  debug = false,
}) => {
  const [engine] = useState(() => {
    const newEngine = Matter.Engine.create();
    newEngine.enableSleeping = false;
    newEngine.gravity.y = 0;
    return newEngine;
  });
  const [isReady, setIsReady] = useState(false);
  const sceneRef = useRef<HTMLDivElement>(null);
  const engineRef = useRef<Matter.Engine | null>(null);
  const renderRef = useRef<Matter.Render | null>(null);
  const runnerRef = useRef<Matter.Runner | null>(null);

  useEffect(() => {
    engineRef.current = engine;
    setIsReady(true);

    // Optional: Debug Renderer
    if (debug && sceneRef.current && engine) {
      const render = Matter.Render.create({
        element: sceneRef.current,
        engine,
        options: {
          width: window.innerWidth,
          height: window.innerHeight,
          wireframes: true, // Set to false for solid colors if needed
          background: "transparent",
        },
      });
      renderRef.current = render;
      Matter.Render.run(render);
    }

    // Create Runner
    if (engine) {
      const runner = Matter.Runner.create();
      runnerRef.current = runner;
      Matter.Runner.run(runner, engine);
    }

    return () => {
      // Cleanup
      if (renderRef.current) {
        Matter.Render.stop(renderRef.current);
        if (renderRef.current.canvas) {
          renderRef.current.canvas.remove();
        }
      }
      if (runnerRef.current) {
        Matter.Runner.stop(runnerRef.current);
      }
      if (engine) {
        Matter.World.clear(engine.world, false);
        Matter.Engine.clear(engine);
      }
    };
  }, [debug, engine]);

  return (
    <PhysicsContext.Provider
      value={{ engine, world: engine?.world || null, isReady }}
    >
      {debug && (
        <div
          className="pointer-events-none absolute inset-0 z-50 opacity-50"
          ref={sceneRef}
        />
      )}
      {children}
    </PhysicsContext.Provider>
  );
};

