  const handleForward = () => {
    if (historyIndex < history.length - 1) {
      const newIndex = historyIndex + 1;
      setHistoryIndex(newIndex);
      const nextUrl = history[newIndex];
      setUrl(nextUrl);
      setInputValue(nextUrl);
      setShowError(BLOCKED_DOMAINS.some((d) => nextUrl.includes(d)));
    }
  };

  const handleRefresh = () => {
    setIsLoading(true);
    if (iframeRef.current) {
      // If currently showing error, try to reload implies trying the URL again
      if (showError) {
        navigate(url); // Re-trigger check
      } else {
        iframeRef.current.src = url;
      }
    }
  };

  const handleHome = () => {
    navigate(HOME_URL);
  };

  const handleIframeLoad = () => {
    setIsLoading(false);
  };

  return (
    <div className="flex h-full flex-col bg-[#dddddd] font-sans">
      {/* IE Toolbar Background with Pinstripes */}
      <div className="flex flex-col gap-2 border-gray-400 border-b bg-[#e8e8e8] bg-[url('https://www.transparenttextures.com/patterns/diagonal-stripes-light.png')] p-2 shadow-sm">
