            src="https://www.razisyed.cv/experiments/non-euclidean-hyperbolic-workspace/escher.png"
          />
          <div className="pointer-events-none absolute inset-0 bg-gradient-to-t from-black/20 to-transparent" />
        </div>
      </div>

      <div className="relative mx-4 flex max-h-[90%] w-full max-w-lg flex-col overflow-hidden rounded-2xl border border-white/10 bg-zinc-950/90 shadow-2xl">
        {/* Header: Title + Close Button */}
        <div className="relative flex-none border-white/5 border-b p-6 pb-4">
          <button
            className="absolute top-4 right-4 rounded-full p-2 text-white/50 transition-colors hover:bg-white/10 hover:text-white"
            onClick={onClose}
          >
            <X size={20} />
          </button>
          <div>
            <h2 className="mb-2 pr-8 font-bold text-white text-xl sm:text-2xl">
              Non-Euclidean Hyperbolic Workspace
            </h2>
            <div className="h-0.5 w-12 rounded-full bg-sky-500/50" />
          </div>
        </div>

        {/* Scrollable Content */}
        <div className="custom-scrollbar flex-1 space-y-6 overflow-y-auto p-6 pt-4 text-zinc-300">
          <div className="space-y-4 text-sm leading-relaxed">
            <section>
              <h3 className="mb-1 font-medium text-sky-400">Concept</h3>
              <p>
                This experiment abandons the standard Euclidean plane of the web
                browser for <strong>Hyperbolic Geometry</strong>, specifically
                utilizing the <strong>Poincaré Disk Model</strong>—the same
                geometry made famous by{" "}
                <span
                  className="inline-block cursor-help border-sky-300/30 border-b text-sky-300 transition-colors hover:border-sky-300"
                  onMouseEnter={() => setIsHoveringEscher(true)}
                  onMouseLeave={() => setIsHoveringEscher(false)}
                  onMouseMove={handleMouseMove}
                >
                  M.C. Escher&apos;s <em>Circle Limit</em> woodcuts
                </span>
                . In this non-Euclidean space, the entire infinite plane is
                mapped onto a finite unit circle.
              </p>
            </section>

            <section>
              <h3 className="mb-1 font-medium text-purple-400">The Math</h3>
              <ul className="list-disc space-y-1 pl-4 text-zinc-400">
                <li>
                  <strong>Poincaré Disk</strong>: A model of hyperbolic geometry
                  where &quot;lines&quot; are circular arcs orthogonal to the
                  boundary circle.
                </li>
                <li>
                  <strong>Möbius Transformations</strong>: Navigation is not
                  simple addition (
                  <span className="font-mono text-zinc-300">x + Δx</span>); it
                  is a complex conformal mapping (
                  <span className="font-mono text-zinc-300">
                    z ↦ (z - a)/(1 - āz)
                  </span>
                  ) that preserves angles but distorts distances.
                </li>
                <li>
                  <strong>Exponential Growth</strong>: The circumference of a
                  halo around a point grows exponentially with radius, allowing
                  for infinite information density at the &quot;horizon&quot;
                  (the edge of the circle).
                </li>
              </ul>
            </section>

            <section>
              <h3 className="mb-1 font-medium text-emerald-400">Interaction</h3>
              <ul className="list-disc space-y-1 pl-4 text-zinc-400">
                <li>
                  <strong>Panning</strong>: Dragging the workspace applies a
                  Möbius transformation to the world, bringing distant (tiny)
                  objects to the center (large) and pushing central objects to
                  the periphery.
                </li>
                <li>
                  <strong>The Horizon</strong>: Items never leave the screen;
                  they simply tessellate and shrink towards the boundary circle,
                  which represents infinity.
                </li>
              </ul>
            </section>

            <div className="rounded-lg border border-white/5 bg-white/5 p-3 text-xs">
              <strong className="mb-1 block text-zinc-200">Controls</strong>
              <div className="grid grid-cols-2 gap-2">
                <span>🖱 Mouse Drag</span>
                <span className="text-zinc-500">
                  Pan the view (apply Möbius transformation)
                </span>
                <span>⌨️ Arrow Keys</span>
                <span className="text-zinc-500">Pan the view</span>
                <span>👆 Click Tile</span>
                <span className="text-zinc-500">
                  (Placeholder) Interaction with nodes
                </span>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

import React, { useMemo } from "react";
import {
  type Complex,
  getGeodesicPath,
  mobiusTransform,
} from "./HyperbolicMath";

interface HyperbolicLinkProps {
  end: Complex;
  start: Complex;
  viewCenter: Complex;
  viewportRadius: number;
}

export const HyperbolicLink = React.memo(function HyperbolicLink({
  start,
  end,
  viewCenter,
  viewportRadius,
}: HyperbolicLinkProps) {
  // 1. Transform logical coordinates to visual coordinates based on current view
  // ViewCenter -> Origin
  const vStart = useMemo(
    () => mobiusTransform(start, viewCenter),
    [start, viewCenter]
  );
  const vEnd = useMemo(
    () => mobiusTransform(end, viewCenter),
    [end, viewCenter]
  );

  // 2. Generate SVG Path for the geodesic
  // We pass the viewport radius so the path string has pixel coordinates
  const pathD = useMemo(() => {
    return getGeodesicPath(vStart, vEnd, viewportRadius);
  }, [vStart, vEnd, viewportRadius]);

  return (
    <path
      d={pathD}
      fill="none"
      opacity="0.6"
      pointerEvents="none"
      stroke="url(#link-gradient)"
      strokeWidth="1.5"
      style={{ filter: "url(#glow)" }}
    />
  );
});

export class Complex {
  constructor(
    public re: number,
    public im: number
  ) {}

  static from(re: number, im = 0) {
    return new Complex(re, im);
  }

  add(other: Complex): Complex {
    return new Complex(this.re + other.re, this.im + other.im);
  }

  sub(other: Complex): Complex {
    return new Complex(this.re - other.re, this.im - other.im);
  }

  mul(other: Complex): Complex {
    return new Complex(
      this.re * other.re - this.im * other.im,
      this.re * other.im + this.im * other.re
    );
  }

  div(other: Complex): Complex {
    const denom = other.re * other.re + other.im * other.im;
    if (denom === 0) {
      throw new Error("Division by zero");
    }
    return new Complex(
      (this.re * other.re + this.im * other.im) / denom,
      (this.im * other.re - this.re * other.im) / denom
    );
  }

  conj(): Complex {
    return new Complex(this.re, -this.im);
  }

  abs(): number {
    return Math.sqrt(this.re * this.re + this.im * this.im);
  }

  // Returns arguments between -pi and pi
  arg(): number {
    return Math.atan2(this.im, this.re);
  }
}

/**
 * Applies a Möbius transformation to a point z on the Poincaré disk.
 * transformation: z -> (z - a) / (1 - conj(a) * z)
 * This maps 'a' to the origin (0,0).
 * 'a' conceptually represents the "center" of the view in Poincaré coordinates.
 */
export function mobiusTransform(z: Complex, a: Complex): Complex {
  // Numerator: z - a
  const num = z.sub(a);

  // Denominator: 1 - conj(a) * z
  const aConj = a.conj();
  const prod = aConj.mul(z);
  const one = new Complex(1, 0);
  const den = one.sub(prod);

  return num.div(den);
}

/**
 * Inverse Möbius transformation.
 * effectively mobiusTransform(z, -a) but careful with signs in the denominator logic
 * Actually, the inverse of M_a(z) = (z - a)/(1 - a_bar z) is M_-a(z) = (z + a)/(1 + a_bar z)
 */
export function inverseMobiusTransform(z: Complex, a: Complex): Complex {
  const num = z.add(a);
  const aConj = a.conj();
  const prod = aConj.mul(z);
  const one = new Complex(1, 0);
  const den = one.add(prod);
  return num.div(den);
}

/**
 * Converts screen coordinates (relative to center, normalized to [-1, 1])
 * to a Complex number representing a point on the Poincaré disk.
 */
export function screenToPoincare(x: number, y: number): Complex {
  // Ensure we are within the unit disk
  const dist = Math.sqrt(x * x + y * y);
  if (dist >= 1) {
    // If outside, clamp to edge (or handle as needed, maybe strictly < 1)
    // Using 0.999 to avoid singularity at the boundary
    const angle = Math.atan2(y, x);
    return new Complex(0.999 * Math.cos(angle), 0.999 * Math.sin(angle));
  }
  return new Complex(x, y);
}

/**
 * Converts a Complex number on the Poincaré disk to screen coordinates
 * (relative to center, normalized to [-1, 1]).
 */
export function poincareToScreen(z: Complex): { x: number; y: number } {
  return { x: z.re, y: z.im };
}

/**
 * Calculates the hyperbolic distance between two points on the Poincaré disk.
 * d(a, b) = 2 * tanh^-1( |(a-b)/(1-a_bar*b)| )
 */
export function hyperbolicDistance(a: Complex, b: Complex): number {
  const diff = a.sub(b);
  const aConj = a.conj();
  const denTerm = aConj.mul(b);
  const complexOne = new Complex(1, 0);
  const den = complexOne.sub(denTerm);

  const fraction = diff.div(den);
  const r = Math.min(fraction.abs(), 0.999_999);

  return 2 * Math.atanh(r);
}

/**
 * Generates an SVG path command for the geodesic segment connecting two points
 * in the Poincaré disk model.
 *
 * @param z1 Start point (Complex, unit disk)
 * @param z2 End point (Complex, unit disk)
 * @param r  Viewport radius in pixels (to scale the output)
 * @returns SVG 'd' attribute string (e.g., "M x1 y1 A ...")
 */
export function getGeodesicPath(z1: Complex, z2: Complex, r: number): string {
  const p1x = z1.re * r;
  const p1y = z1.im * r;
  const p2x = z2.re * r;
  const p2y = z2.im * r;

  // Check for collinearity with origin (straight line case)
  // Cross product of vectors z1 and z2.
  // If they are collinear with origin, the geodesic is a straight line.
  const cross = z1.re * z2.im - z1.im * z2.re;

  // Threshold for straight line
  if (Math.abs(cross) < 1e-6) {
    return `M ${p1x.toFixed(2)} ${p1y.toFixed(2)} L ${p2x.toFixed(2)} ${p2y.toFixed(2)}`;
  }

  // General case: Arc of a circle orthogonal to the unit disk.
  // To find this circle, we use the property that it passes through z1, z2,
  // and the inverse of z1 relative to the unit circle (z1_inv = 1 / conj(z1)).

  const denom = z1.re * z1.re + z1.im * z1.im;
  if (denom < 1e-9) {
    // z1 is origin, straight line to z2
    return `M ${p1x.toFixed(2)} ${p1y.toFixed(2)} L ${p2x.toFixed(2)} ${p2y.toFixed(2)}`;
  }

  const z1Inv = new Complex(z1.re / denom, -z1.im / denom); // 1/conj(z1)

  // Now find circle passing through z1, z2, z1Inv.
  // Circle equation: |z - c|^2 = R^2
  // This is a standard "Circle from 3 points" problem.
  // Let's use a determinant method or algebraic solver.
  // D = 2(x1(y2 - y3) + x2(y3 - y1) + x3(y1 - y2))

  const x1 = z1.re,
    y1 = z1.im;
  const x2 = z2.re,
    y2 = z2.im;
  const x3 = z1Inv.re,
    y3 = z1Inv.im;

  const D = 2 * (x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2));

  if (Math.abs(D) < 1e-9) {
    // Points are collinear -> Straight line (should have caught above, but safety fallback)
    return `M ${p1x.toFixed(2)} ${p1y.toFixed(2)} L ${p2x.toFixed(2)} ${p2y.toFixed(2)}`;
  }

  const N1 = x1 * x1 + y1 * y1;
  const N2 = x2 * x2 + y2 * y2;
  const N3 = x3 * x3 + y3 * y3;

  const cx = (N1 * (y2 - y3) + N2 * (y3 - y1) + N3 * (y1 - y2)) / D;
  const cy = (N1 * (x3 - x2) + N2 * (x1 - x3) + N3 * (x2 - x1)) / D;

  const R_unit = Math.sqrt((cx - x1) ** 2 + (cy - y1) ** 2);

  // Convert circle params to screen space
  const R_screen = R_unit * r;

  // SVG Arc Command: A rx ry x-axis-rotation large-arc-flag sweep-flag x y
  // For orthogonal circles in the Poincaré disk, the center of the defining circle is always
  // outside the unit disk. The arc connecting two points inside the unit disk is unique
  // and relatively short (never > 180 degrees of the orthogonal circle if contained in unit disk).
  // Thus large-arc-flag is 0.
  // sweep-flag '1' works for the standard coordinate system where +y is down,
  // assuming consistent vertex ordering. If needed, a cross-product check can enforce
  // convexity towards the origin, but current visual tests show stability.

  return `M ${p1x.toFixed(2)} ${p1y.toFixed(2)} A ${R_screen.toFixed(2)} ${R_screen.toFixed(2)} 0 0 1 ${p2x.toFixed(2)} ${p2y.toFixed(2)}`;
}

import React, { useMemo } from "react";
import { cn } from "@/lib/utils";
import {
  type Complex,
  mobiusTransform,
  poincareToScreen,
} from "./HyperbolicMath";

// Constants for visual logic
const TILE_BASE_SIZE = 100; // base size in pixels at the center

interface HyperbolicTileProps {
  /** Optional content/label */
  children?: React.ReactNode;
  className?: string;
  /** The logical center of this tile in the Poincaré disk (before any view panning) */
  logicalPosition: Complex;
  onClick?: () => void;
  /** The current "view" center (the point in the Poincaré disk that is currently at the screen center) */
  viewCenter: Complex;
  /** Radius of the viewport in pixels, used for converting unit coords to screen pixels */
  viewportRadius: number;
}

export function HyperbolicTile({
  logicalPosition,
  viewCenter,
  viewportRadius,
  children,
  className,
  onClick,
}: HyperbolicTileProps) {
  // 1. Apply the view transformation: move 'viewCenter' to origin
  // The transformation M(z) = (z - a) / (1 - conj(a)*z) maps 'a' to 0.
  const visualPositionComplex = useMemo(() => {
    return mobiusTransform(logicalPosition, viewCenter);
  }, [logicalPosition, viewCenter]);

  // 2. Convert to screen coordinates (unit disk [-1, 1])
  const { x: unitX, y: unitY } = poincareToScreen(visualPositionComplex);

  // 3. Calculate distance from center to determine scale
  // In the Poincaré disk, Euclidean size shrinks as we get closer to the edge.
  // A simple approximation is scaling by (1 - r^2) or similar metric,
  // but strictly speaking, we want conformal scaling.
  // The derivative of the Möbius transform gives the local scaling factor.
  // |M'(z)| = (1 - |a|^2) / |1 - conj(a)z|^2
  // However, for "visual shrinking" towards the edge of the disk (which represents infinity),
  // we can use a scaling factor proportional to the Euclidean metric distortion:
  // scale ~ 1 - r^2  (at r=0 scale=1, at r=1 scale=0)
  const rSquared = unitX * unitX + unitY * unitY;
  const scale = Math.max(0, 1 - rSquared);

  // If tile is too small, don't render it to save performance/visual noise
  if (scale < 0.05) {
    return null;
  }

  // 4. Map unit coordinates to pixel coordinates relative to container center
  const pixelX = unitX * viewportRadius;
  const pixelY = unitY * viewportRadius;

  return (
    <div
      aria-label={`Navigate to ${typeof children === "string" ? children : "node"}`}
      className={cn(
        "absolute flex cursor-pointer select-none items-center justify-center rounded-xl transition-all duration-300 ease-out",
        // Remove default strong gradient, rely on passed className for coloring
        "font-bold text-white",
        "hover:z-50 hover:scale-110 hover:brightness-125",
        className
      )}
      onClick={onClick}
      role="button"
      style={{
        width: `${TILE_BASE_SIZE}px`,
        height: `${TILE_BASE_SIZE}px`,
        willChange: "transform",
        // Use fixed precision to avoid hydration mismatches between server (node) and client (browser) floating point stringification
        transform: `translate3d(${pixelX.toFixed(4)}px, ${pixelY.toFixed(4)}px, 0px) scale(${scale.toFixed(6)})`,
        // Center the element at non-transformed origin so translation works from center
        marginLeft: `-${TILE_BASE_SIZE / 2}px`,
        marginTop: `-${TILE_BASE_SIZE / 2}px`,
        left: "50%",
        top: "50%",
        zIndex: Math.floor(scale * 100), // Larger items on top
      }}
    >
      <div className="overflow-hidden p-2 text-center text-xs">
        {children || "Tile"}
      </div>
    </div>
  );
}

// Optimization: Memoize tile to prevent re-renders if pos/viewCenter are stable (though they change every frame during drag)
export const HyperbolicTileMemo = React.memo(HyperbolicTile);

"use client";

import { useFrame, useThree } from "@react-three/fiber";
import { useEffect, useRef } from "react";
import type * as THREE from "three";
import VisualiserLogic from "./VisualiserLogic";

export default function GalleryExploreScene() {
  const { scene, camera, gl } = useThree();
  const visualiserManager = useRef<VisualiserLogic | null>(null);

  useEffect(() => {
    // Calculate world dimensions at z=0 (where planes are roughly)
    // Camera default z pos needs to be known.
    // If we assume camera z=10 like reference

    // Ensure camera is positioned as expected if not controlled elsewhere
    // But usually we control camera in Page or Canvas.
    // We'll read the current camera position.

    const cam = camera as THREE.PerspectiveCamera;
    // We assume looking at z=0.
    const distance = cam.position.z;
    const vFov = (cam.fov * Math.PI) / 180;
    const height = 2 * Math.tan(vFov / 2) * distance;
    const width = height * cam.aspect;

    if (cam.position.z < 0.1) {
      console.warn("Camera z is too close or 0, calculation might be wrong");
    }

    const sizes = { width, height };

    visualiserManager.current = new VisualiserLogic({ scene, sizes, camera });
    visualiserManager.current.bindDrag(gl.domElement);

    return () => {
      visualiserManager.current?.dispose();
    };
  }, [scene, camera, gl.domElement]); // Re-init if scene/camera changes seriously, though unlikely.

  useFrame((_state, delta) => {
    visualiserManager.current?.render(delta);
  });

  return null;
}

import normalizeWheel from "normalize-wheel";
import * as THREE from "three";
import { fragmentShader, vertexShader } from "./shaders";

interface Size {
  height: number;
  width: number;
}

interface Props {
  camera: THREE.Camera;
  scene: THREE.Scene;
  sizes: Size;
}

interface ImageInfo {
  aspectRatio: number;
  height: number;
  uvs: {
    xStart: number;
    xEnd: number;
    yStart: number;
    yEnd: number;
  };
  width: number;
}

export default class VisualiserLogic {
  scene: THREE.Scene;
  geometry!: THREE.PlaneGeometry;
  material!: THREE.ShaderMaterial;
  mesh!: THREE.InstancedMesh;
  meshCount = 400;
  sizes: Size;
  drag: {
    xCurrent: number;
    xTarget: number;
    yCurrent: number;
    yTarget: number;
    isDown: boolean;
    startX: number;
    startY: number;
    lastX: number;
    lastY: number;
  } = {
    xCurrent: 0,
    xTarget: 0,
    yCurrent: 0,
    yTarget: 0,
    isDown: false,
    startX: 0,
    startY: 0,
    lastX: 0,
    lastY: 0,
  };
  shaderParameters = {
    maxX: 0,
    maxY: 0,
  };
  scrollY: {
    target: number;
    current: number;
    direction: number;
  } = {
    target: 0,
    current: 0,
    direction: 0,
  };
  dragSensitivity = 1;
  dragDamping = 0.1;
  dragElement?: HTMLElement;
  imageInfos: ImageInfo[] = [];
  atlasTexture: THREE.Texture | null = null;
  blurryAtlasTexture: THREE.Texture | null = null;

  camera: THREE.Camera;
  raycaster: THREE.Raycaster = new THREE.Raycaster();

  constructor({ scene, sizes, camera }: Props) {
    this.scene = scene;
    this.sizes = sizes;
    this.camera = camera;

    this.shaderParameters = {
      maxX: this.sizes.width * 2,
      maxY: this.sizes.height * 2,
    };

    this.createGeometry();
    this.createMaterial();
    this.createInstancedMesh();
    this.fetchCovers();

    // We'll manage event listeners in the React component or ensure cleanup if we add them here
    // For now, let's keep the global wheel for simplicity, but we should adding a cleanup method.
    window.addEventListener("wheel", this.onWheel);
  }

  dispose() {
    window.removeEventListener("wheel", this.onWheel);
    if (this.dragElement) {
      this.dragElement.removeEventListener("pointerdown", this._onPointerDown);
      window.removeEventListener("pointermove", this._onPointerMove);
      window.removeEventListener("pointerup", this._onPointerUp);
    }
    this.geometry.dispose();
    this.material.dispose();
    // Dispose textures
    this.atlasTexture?.dispose();
    this.blurryAtlasTexture?.dispose();
  }

  createGeometry() {
    this.geometry = new THREE.PlaneGeometry(1, 1, 1, 1);
    // Scale to a good base size
    this.geometry.scale(2, 2, 2);
  }

  async fetchCovers() {
    // Load local frames
    const urls: string[] = new Array(20)
      .fill(0)
      .map(
        (_, i) => `https://www.razisyed.cv/experiments/rabbithole-chat-preloader/frames/${i + 1}.jpg`
      );

    await this.loadTextureAtlas(urls);
    this.createBlurryAtlas();
    this.fillMeshData();
  }

  async loadTextureAtlas(urls: string[]) {
    // Load all images with CORS-safe approach
    const imagePromises = urls.map(async (path) => {
      try {
        const res = await fetch(path, { mode: "cors" });
        if (!res.ok) {
          throw new Error(`Failed to fetch image: ${path}`);
        }
        const blob = await res.blob();
        const bitmap = await createImageBitmap(blob);
        return bitmap as CanvasImageSource;
      } catch {
        // Fallback to HTMLImageElement with crossOrigin
        return await new Promise<CanvasImageSource>((resolve, reject) => {
          const img = new Image();
          img.crossOrigin = "anonymous";
          img.onload = () => resolve(img);
          img.onerror = (e) => reject(e);
          img.src = path;
        });
      }
    });

    const images = await Promise.all(imagePromises);
    if (images.length === 0) {
      return;
    }

    // Calculate atlas dimensions (stacking vertically)
    // We need to cast to any or a type with width/height because CanvasImageSource union is tricky
    const atlasWidth = Math.max(
      ...images.map((img) => (img as { width: number }).width)
    );
    let totalHeight = 0;

    // First pass: calculate total height with padding to prevent bleeding
    const padding = 2;
    images.forEach((img) => {
      totalHeight += (img as { height: number }).height + padding;
    });

    // Create canvas
    const canvas = document.createElement("canvas");
    canvas.width = atlasWidth;
    canvas.height = totalHeight;
    const ctx = canvas.getContext("2d")!;

    // Second pass: draw images and calculate normalized coordinates
    let currentY = 0;
    this.imageInfos = images.map((img) => {
      // Cast to standard type that has width/height
      // We use 'as any' for drawImage to satisfy the overload, but stricter typing for properties
      const source = img as { width: number; height: number };
      const aspectRatio = source.width / source.height;

      // Draw the image with rounded corners
      // Radius ~40px to look like 1rem on these large ~1000px images
      const r = 40;
      const x = 0;
      const y = currentY;
      const w = source.width;
      const h = source.height;

      ctx.save();
      ctx.beginPath();
      ctx.moveTo(x + r, y);
      ctx.lineTo(x + w - r, y);
      ctx.quadraticCurveTo(x + w, y, x + w, y + r);
      ctx.lineTo(x + w, y + h - r);
      ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
      ctx.lineTo(x + r, y + h);
      ctx.quadraticCurveTo(x, y + h, x, y + h - r);
      ctx.lineTo(x, y + r);
      ctx.quadraticCurveTo(x, y, x + r, y);
      ctx.closePath();
      ctx.clip();

      ctx.drawImage(img as CanvasImageSource, 0, currentY);
      ctx.restore();

      const info = {
        width: source.width,
        height: source.height,
        aspectRatio,
        uvs: {
          xStart: 0,
          xEnd: source.width / atlasWidth,

          // Invert Y for UVs (Canvas 0 is Top, UV 0 is Bottom)
          // We map the image area [currentY, currentY + height]
          yStart: 1 - currentY / totalHeight,
          yEnd: 1 - (currentY + source.height) / totalHeight,
        },
      };

      currentY += source.height + padding;
      return info;
    });

    // Create texture from canvas
    this.atlasTexture = new THREE.Texture(canvas);
    this.atlasTexture.wrapS = THREE.ClampToEdgeWrapping;
    this.atlasTexture.wrapT = THREE.ClampToEdgeWrapping;
    this.atlasTexture.minFilter = THREE.LinearFilter;
    this.atlasTexture.magFilter = THREE.LinearFilter;
    // Fix premultiplied alpha issue:
    // Canvas is premultiplied. If we tell Three.js this, it might blending better.
    // However, standard technique with transparency is usually straight alpha in Three.
    // Let's rely on the shader discard for the artifacts.
    this.atlasTexture.needsUpdate = true;
    this.material.uniforms.uAtlas.value = this.atlasTexture;
  }

  createBlurryAtlas() {
    if (!this.atlasTexture) {
      return;
    }

    const source = this.atlasTexture.image as HTMLCanvasElement;
    const blurryCanvas = document.createElement("canvas");
    blurryCanvas.width = source.width;
    blurryCanvas.height = source.height;
    const ctx = blurryCanvas.getContext("2d")!;
    ctx.filter = "blur(100px)";
    ctx.drawImage(source, 0, 0);

    this.blurryAtlasTexture = new THREE.Texture(blurryCanvas);
    this.blurryAtlasTexture.wrapS = THREE.ClampToEdgeWrapping;
    this.blurryAtlasTexture.wrapT = THREE.ClampToEdgeWrapping;
    this.blurryAtlasTexture.minFilter = THREE.LinearFilter;
    this.blurryAtlasTexture.magFilter = THREE.LinearFilter;
    this.blurryAtlasTexture.needsUpdate = true;
    this.material.uniforms.uBlurryAtlas.value = this.blurryAtlasTexture;
  }

  createMaterial() {
    this.material = new THREE.ShaderMaterial({
      vertexShader,
      fragmentShader,
      transparent: true,
      side: THREE.DoubleSide,
      uniforms: {
        uTime: { value: 0 },
        uMaxXdisplacement: {
          value: new THREE.Vector2(
            this.shaderParameters.maxX,
            this.shaderParameters.maxY
          ),
        },
        uAtlas: new THREE.Uniform(this.atlasTexture),
        uBlurryAtlas: new THREE.Uniform(this.blurryAtlasTexture),
        uScrollY: { value: 0 },
        uSpeedY: { value: 0 },
        uDrag: { value: new THREE.Vector2(0, 0) },
      },
    });
  }

  createInstancedMesh() {
    this.mesh = new THREE.InstancedMesh(
      this.geometry,
      this.material,
      this.meshCount
    );
    this.scene.add(this.mesh);
  }

  fillMeshData() {
    if (this.imageInfos.length === 0) {
      return;
    }

    const initialPosition = new Float32Array(this.meshCount * 3);
    const meshSpeed = new Float32Array(this.meshCount);
    const aTextureCoords = new Float32Array(this.meshCount * 4);

    for (let i = 0; i < this.meshCount; i++) {
      // Random positions
      initialPosition[i * 3 + 0] =
        (Math.random() - 0.5) * this.shaderParameters.maxX * 2; // x
      initialPosition[i * 3 + 1] =
        (Math.random() - 0.5) * this.shaderParameters.maxY * 2; // y

      //from -15 to 7 - Depth
      initialPosition[i * 3 + 2] = Math.random() * (7 - -30) - 30; // z

      meshSpeed[i] = Math.random() * 0.5 + 0.5;

      const imageIndex = i % this.imageInfos.length;

      aTextureCoords[i * 4 + 0] = this.imageInfos[imageIndex].uvs.xStart;
      aTextureCoords[i * 4 + 1] = this.imageInfos[imageIndex].uvs.xEnd;
      aTextureCoords[i * 4 + 2] = this.imageInfos[imageIndex].uvs.yStart;
      aTextureCoords[i * 4 + 3] = this.imageInfos[imageIndex].uvs.yEnd;
    }

    this.geometry.setAttribute(
      "aInitialPosition",
      new THREE.InstancedBufferAttribute(initialPosition, 3)
    );
    this.geometry.setAttribute(
      "aMeshSpeed",
      new THREE.InstancedBufferAttribute(meshSpeed, 1)
    );

    this.mesh.geometry.setAttribute(
      "aTextureCoords",
      new THREE.InstancedBufferAttribute(aTextureCoords, 4)
    );

    // Add aspect ratio attribute
    const aAspectRatio = new Float32Array(this.meshCount);
    for (let i = 0; i < this.meshCount; i++) {
      const imageIndex = i % this.imageInfos.length;
      aAspectRatio[i] = this.imageInfos[imageIndex].aspectRatio;
    }
    this.mesh.geometry.setAttribute(
      "aAspectRatio",
      new THREE.InstancedBufferAttribute(aAspectRatio, 1)
    );
  }

  private _onPointerDown = (e: PointerEvent) => {
    this.drag.isDown = true;
    this.drag.startX = e.clientX;
    this.drag.startY = e.clientY;
    this.drag.lastX = e.clientX;
    this.drag.lastY = e.clientY;
    if (this.dragElement) {
      this.dragElement.setPointerCapture(e.pointerId);
    }
  };

  private _onPointerMove = (e: PointerEvent) => {
    if (!this.drag.isDown) {
      return;
    }
    const dx = e.clientX - this.drag.lastX;
    const dy = e.clientY - this.drag.lastY;
    this.drag.lastX = e.clientX;
    this.drag.lastY = e.clientY;

    // Convert pixels to world units proportionally to viewport size
    const worldPerPixelX =
      (this.sizes.width / window.innerWidth) * this.dragSensitivity;
    const worldPerPixelY =
      (this.sizes.height / window.innerHeight) * this.dragSensitivity;

    this.drag.xTarget += -dx * worldPerPixelX;
    this.drag.yTarget += dy * worldPerPixelY;
  };

  private _onPointerUp = (e: PointerEvent) => {
    const dx = e.clientX - this.drag.startX;
    const dy = e.clientY - this.drag.startY;
    const dist = Math.sqrt(dx * dx + dy * dy);

    // If movement is very small, treat as click
    if (dist < 5) {
      this.handleClick(e.clientX, e.clientY);
    }

    this.drag.isDown = false;
    try {
      if (this.dragElement) {
        this.dragElement.releasePointerCapture(e.pointerId);
      }
    } catch {}
  };

  handleClick(clientX: number, clientY: number) {
    // Normalize mouse coordinates
    const mouse = new THREE.Vector2(
      (clientX / window.innerWidth) * 2 - 1,
      -(clientY / window.innerHeight) * 2 + 1
    );

    this.raycaster.setFromCamera(mouse, this.camera);

    // CPU-side "raycasting" by checking intersection with each plane's computed position
    const attributes = this.geometry.attributes;
    const aInitialPosition = attributes.aInitialPosition;
    const aMeshSpeed = attributes.aMeshSpeed;
    const aAspectRatioBuffer = this.mesh.geometry.attributes.aAspectRatio;

    const uniforms = this.material.uniforms;
    const uTime = uniforms.uTime.value;
    const uDrag = uniforms.uDrag.value;
    const uScrollY = uniforms.uScrollY.value;
    const uMaxX = uniforms.uMaxXdisplacement.value.x;
    const uMaxY = uniforms.uMaxXdisplacement.value.y;

    // Constants from shader
    const maxZ = 12.0;
    const minZ = -30.0;
    const floatSpeed = 0.5;
    const floatAmp = 0.2;

    let closestDist = Number.POSITIVE_INFINITY;
    let hitIndex = -1;

    // Plane normal is +Z (0, 0, 1) since they face the camera and are not rotated
    const planeNormal = new THREE.Vector3(0, 0, 1);
    const rayDir = this.raycaster.ray.direction;
    const rayOrigin = this.raycaster.ray.origin;

    for (let i = 0; i < this.meshCount; i++) {
      // Replicate Shader Logic
      const ix = aInitialPosition.getX(i);
      const iy = aInitialPosition.getY(i);
      const iz = aInitialPosition.getZ(i);
      const speed = aMeshSpeed.getX(i);
      const aspectRatio = aAspectRatioBuffer.getX(i);

      // Displacement calculations
      const maxZoffset = Math.abs(iz - maxZ); // distance logic: distance(a, b) = abs(a-b) in 1D
      const minZoffset = Math.abs(iz - minZ);

      // mod logic: mod(a, b) = a - b * floor(a/b). JS % operator matches if positive, check signs.
      // Shader uses floats. JS % can return negative.
      // Helper for shader mod:
      const shaderMod = (x: number, y: number) => {
        return x - y * Math.floor(x / y);
      };

      const zDisp =
        shaderMod(uScrollY + minZoffset, maxZoffset + minZoffset) - minZoffset;

      // Floating effect
      const zFloat = Math.sin(uTime * floatSpeed * speed + ix) * floatAmp;

      const currentZ = iz + zDisp + zFloat;

      // Check Visibility (optimization)
      // vVisibility = remap(newPosition.z, minZ, minZ+5.);
      // If z < minZ, it's fading out/invisible? Remap clamps [0,1].
      // If z is way behind or too far, maybe skip.
      // Current depth range in shader: usually visible between minZ and maxZ.

      // Calculating Plane intersection
      // Ray: O + tD. Plane: (P - Center) . N = 0
      // t = (Center - O) . N / (D . N)
      // Center.z is currentZ. Center.x/y needed?
      // Plane is at Z = currentZ.

      const denom = rayDir.dot(planeNormal);
      if (Math.abs(denom) < 1e-6) {
        continue; // Parallel to plane
      }

      const t = (currentZ - rayOrigin.z) / denom;
      if (t < 0) {
        continue; // Behind ray start
      }

      // Intersection point
      const intersectPoint = new THREE.Vector3()
        .copy(rayOrigin)
        .addScaledVector(rayDir, t);

      // Now check if intersection point is within the rectangle bounds of this instance
      // Need X and Y position of instance
      const maxYoffset = Math.abs(iy - uMaxY);
      const minYoffset = Math.abs(iy + uMaxY); // -(-maxY) = +maxY

      const maxXoffset = Math.abs(ix - uMaxX);
      const minXoffset = Math.abs(ix + uMaxX);

      const xDisp =
        shaderMod(
          minXoffset - uDrag.x + uTime * speed,
          maxXoffset + minXoffset
        ) - minXoffset;
      const yDisp =
        shaderMod(minYoffset - uDrag.y, maxYoffset + minYoffset) - minYoffset;

      // Aspect ratio scaling applies to Y coordinate of 'position' (vertex), not the translation.
      // Shader: newPosition.y /= aAspectRatio; newPosition += aInitialPosition;
      // So the CENTER is at (ix + xDisp, iy + yDisp).
      // The EXTENT (half-size) of the plane geometry is:
      // Base scaled (2,2,2) -> width 2, height 2.
      // Aspect applied: width 2, height 2 / aspectRatio.
      // Half-width: 1.0
      // Half-height: 1.0 / aspectRatio

      const centerX = ix + xDisp;
      const centerY = iy + yDisp;

      const dx = Math.abs(intersectPoint.x - centerX);
      const dy = Math.abs(intersectPoint.y - centerY);

      if (dx <= 1.0 && dy <= 1.0 / aspectRatio) {
        // Hit!
        // Check if this is closer than previous hits
        if (t < closestDist) {
          closestDist = t;
          hitIndex = i;
        }
      }
    }

    if (hitIndex !== -1) {
      window.open(
        "https://www.rabbithole.chat/rabbithole/how-did-humans-first-7kjxug9e",
        "_blank"
      );
    }
  }

  bindDrag(element: HTMLElement) {
    this.dragElement = element;
    element.addEventListener("pointerdown", this._onPointerDown);
    window.addEventListener("pointermove", this._onPointerMove);
    window.addEventListener("pointerup", this._onPointerUp);
  }

  onWheel = (event: MouseEvent) => {
    const normalizedWheel = normalizeWheel(event);

    const scrollY =
      (normalizedWheel.pixelY * this.sizes.height) / window.innerHeight;

    this.scrollY.target += scrollY;

    this.material.uniforms.uSpeedY.value += scrollY;
  };

  render(delta: number) {
    // Reference uses normalized delta (approx 1.0 for 60fps)
    // R3F gives delta in seconds (approx 0.016 for 60fps)
    // We multiply by 60 to match the reference logic scale
    const normalizedDelta = delta * 60;

    this.material.uniforms.uTime.value += normalizedDelta * 0.005;

    // Smoothly interpolate current drag towards target
    this.drag.xCurrent +=
      (this.drag.xTarget - this.drag.xCurrent) *
      this
        .dragDamping; /* * normalizedDelta? Reference didn't use it for lerp but maybe implicitly expected it? */
    // Reference code:
    // this.drag.xCurrent += (this.drag.xTarget - this.drag.xCurrent) * this.dragDamping
    // It did NOT use delta. So damping is framerate dependent in reference.
    // We will keep it as is for now to match reference exactly, assuming 60fps.
    this.drag.yCurrent +=
      (this.drag.yTarget - this.drag.yCurrent) * this.dragDamping;

    this.material.uniforms.uDrag.value.set(
      this.drag.xCurrent,
      this.drag.yCurrent
    );

    this.scrollY.current = interpolate(
      this.scrollY.current,
      this.scrollY.target,
      0.12
    );

    this.material.uniforms.uScrollY.value = this.scrollY.current;
    this.material.uniforms.uSpeedY.value *= 0.835;
  }
}

const interpolate = (current: number, target: number, ease: number) => {
  return current + (target - current) * ease;
};

export const vertexShader = `
varying vec2 vUv;

attribute vec3 aInitialPosition;
attribute float aMeshSpeed;
attribute vec4 aTextureCoords;
attribute float aAspectRatio;


uniform float uTime;
uniform vec2 uMaxXdisplacement;
uniform vec2 uDrag;

uniform float uSpeedY;
uniform float uScrollY;


varying float vVisibility;
varying vec4 vTextureCoords;


//linear smoothstep
float remap(float value, float originMin, float originMax)
{
    return clamp((value - originMin) / (originMax - originMin),0.,1.);
}

void main()
{     

    vec3 newPosition=position;
    // Apply aspect ratio scaling
    // Assuming base geometry is square 1x1. AspectRatio = width/height.
    // We keep width constant and adjust height? Or vice versa.
    // Preloader did: scaledPosition.y/=aAspectRatio;
    // If AR=2 (wide), y becomes 0.5. Result 1x0.5 -> 2:1. Correct.
    newPosition.y /= aAspectRatio;

    newPosition += aInitialPosition;


    float maxX = uMaxXdisplacement.x;
    float maxY = uMaxXdisplacement.y;

    float maxYoffset = distance(aInitialPosition.y,maxY);
    float minYoffset = distance(aInitialPosition.y,-maxY);


    float maxXoffset = distance(aInitialPosition.x,maxX);
    float minXoffset = distance(aInitialPosition.x,-maxX);


    float xDisplacement = mod(minXoffset -uDrag.x + uTime * aMeshSpeed, maxXoffset+minXoffset) - minXoffset;
    float yDisplacement = mod(minYoffset -uDrag.y, maxYoffset+minYoffset) - minYoffset;

    // Modified depth range for better visibility with our camera setup
    float maxZ = 12.;
    float minZ = -30.;

    float maxZoffset = distance(aInitialPosition.z,maxZ);    
    float minZoffset = distance(aInitialPosition.z,minZ);    

    float zDisplacement = mod(uScrollY + minZoffset,maxZoffset + minZoffset ) - minZoffset;    

    // Add extra "floating" movement on Z and Y axis for liveness
    float floatSpeed = 0.5;
    float floatAmp = 0.2;
    newPosition.z += sin(uTime * floatSpeed * aMeshSpeed + aInitialPosition.x) * floatAmp;

    newPosition.x += xDisplacement; 
    newPosition.y += yDisplacement;
    newPosition.z += zDisplacement;


    vVisibility = remap(newPosition.z, minZ, minZ+5.);


    vec4 modelPosition = modelMatrix * instanceMatrix * vec4(newPosition, 1.0);        


    vec4 viewPosition = viewMatrix * modelPosition;
    vec4 projectedPosition = projectionMatrix * viewPosition;
    gl_Position = projectedPosition;    

    vUv = uv;
    vTextureCoords = aTextureCoords;
}
`;

export const fragmentShader = `
varying vec2 vUv;
varying float vVisibility;
varying vec4 vTextureCoords;

uniform sampler2D uAtlas;
uniform sampler2D uBlurryAtlas;

void main()
{            
    // Get UV coordinates for this image from the uniform array
    float xStart = vTextureCoords.x;
    float xEnd = vTextureCoords.y;
    float yStart = vTextureCoords.z;
    float yEnd = vTextureCoords.w;

     vec2 atlasUV = vec2(
        mix(xStart, xEnd, vUv.x),
        mix(yStart, yEnd, 1.-vUv.y) // Inverted Y for correct orientation
    );     

    vec2 atlasUV_standard = vec2(
        mix(xStart, xEnd, vUv.x),
        mix(yStart, yEnd, 1.-vUv.y)
    );

    vec4 color = texture2D(uAtlas, atlasUV_standard);

    // Tighten alpha to remove dark halos from canvas anti-aliasing
    // Canvas alpha is often premultiplied or blended with black, causing dark edges when linear filtered.
    // We boost the alpha curve to cut out the semi-transparent black fringe.
    color.a = smoothstep(0.01, 0.1, color.a) * color.a;
    if (color.a < 0.01) discard;

    color.a *= vVisibility;

    // Saturation/Brightness caps from original
    color.r = min(color.r, 1.);
    color.g = min(color.g, 1.);
    color.b = min(color.b, 1.);

    gl_FragColor = color;
}
`;

