          {/* Expanded Controls */}
          <ExpandedControls
            deepSearchActive={deepSearchActive}
            isVisible={isExpanded}
            onDeepSearchToggle={() => setDeepSearchActive((a) => !a)}
            onThinkToggle={() => setThinkActive((a) => !a)}
