export function useTransitData(agency = "caltrain") {
  const [data, setData] = useState<TransitTrip[]>([]);
  const [loading, setLoading] = useState(true);
  const [prevAgency, setPrevAgency] = useState(agency);

  if (agency !== prevAgency) {
    setPrevAgency(agency);
    setLoading(true);
  }

  useEffect(() => {
    // Simulate initial fetch with a slight delay
    const timer = setTimeout(() => {
      setData(agency === "ttc" ? TTC_MOCK : CALTRAIN_MOCK);
      setLoading(false);
    }, 800);

    // Simulate occasional updates or status changes
    const interval = setInterval(() => {
      setData((current) =>
        current.map((trip) => {
          if (Math.random() > 0.85) {
            const statuses: TransitTrip["status"][] = [
              "ON TIME",
              "DELAYED",
              "BOARDING",
              "DEPARTED",
            ];
            return {
              ...trip,
              status: statuses[Math.floor(Math.random() * statuses.length)],
            };
          }
          return trip;
        })
      );
    }, 12_000);

    return () => {
      clearTimeout(timer);
      clearInterval(interval);
    };
  }, [agency]);

  return { data, loading };
}

