import type React from "react";
import { SPRING_CONFIGS } from "./constants";
import { useVelocityState } from "./VelocityContext";

interface VelocityCodeBlockProps {
  code: string;
  filename: string;
  language: string;
}

export const VelocityCodeBlock: React.FC<VelocityCodeBlockProps> = ({
  filename,
  language,
  code,
}) => {
  const { readingState } = useVelocityState();
  const isSkim = readingState === "skim";

  return (
    <motion.div
      animate={{
        scale: isSkim ? 0.98 : 1,
        opacity: isSkim ? 0.8 : 1,
      }}
      className={`my-8 overflow-hidden rounded-lg border ${
        isSkim
          ? "border-primary/20 bg-primary/5"
          : "border-white/10 bg-zinc-950"
      }`}
      layout
      transition={SPRING_CONFIGS.TRANSITION}
    >
      <div className="flex items-center justify-between border-white/5 border-b bg-white/5 px-4 py-2">
        <div className="flex items-center gap-2">
          <FileCode className="text-primary" size={14} />
          <span className="font-mono text-muted-foreground text-xs">
            {filename}
          </span>
        </div>
        <span className="text-[10px] text-muted-foreground/50 uppercase tracking-widest">
          {language}
        </span>
      </div>

      <AnimatePresence initial={false} mode="popLayout">
        {isSkim ? (
          <motion.div
            animate={{ opacity: 1, scale: 1 }}
            className="relative flex h-10 items-center gap-3 overflow-hidden px-4 text-primary/60 text-sm italic"
            exit={{ opacity: 0, scale: 0.98 }}
            initial={{ opacity: 0, scale: 1.02 }}
            key="skim"
          >
            <motion.div
              animate={{ x: ["-100%", "200%"] }}
              className="pointer-events-none absolute inset-0 bg-gradient-to-r from-transparent via-primary/5 to-transparent"
              transition={{
                duration: 1.5,
                repeat: Number.POSITIVE_INFINITY,
                ease: "linear",
              }}
            />
            <Terminal size={14} />
            <span>Implementation details collapsed for speed...</span>
          </motion.div>
        ) : (
          <motion.div
            animate={{ opacity: 1, scale: 1 }}
            className="overflow-x-auto p-4"
            exit={{ opacity: 0, scale: 1.02 }}
            initial={{ opacity: 0, scale: 0.98 }}
            key="detailed"
          >
            <pre className="font-mono text-sm text-zinc-300">
              <code>{code}</code>
            </pre>
          </motion.div>
        )}
      </AnimatePresence>
    </motion.div>
  );
};

"use client";

import { useScroll, useSpring, useVelocity } from "motion/react";
import React, { createContext, useContext, useEffect, useState } from "react";
import { SPRING_CONFIGS, TIMINGS, VELOCITY_THRESHOLDS } from "./constants";

type ReadingState = "detailed" | "skim";

interface VelocityContextType {
  isScrolling: boolean;
  lockVelocity: () => void;
  manualVelocity: number | null;
  normalizedVelocity: number; // 0 to 1
  readingState: ReadingState;
  setManualVelocity: (v: number | null) => void;
  velocity: number;
}

const VelocityContext = createContext<VelocityContextType | undefined>(
  undefined
);

export const VelocityProvider: React.FC<{ children: React.ReactNode }> = ({
  children,
}) => {
  const { scrollY } = useScroll();
  const scrollVelocity = useVelocity(scrollY);

  // Use a spring to smooth out the velocity values for UI transitions
  const smoothVelocity = useSpring(
    scrollVelocity,
    SPRING_CONFIGS.VELOCITY_SMOOTHING
  );

  const [scrollV, setScrollV] = useState(0);
  const [manualVelocity, setManualVelocity] = useState<number | null>(null);
  const [readingState, setReadingState] = useState<ReadingState>("detailed");
  const [isVelocityLocked, setIsVelocityLocked] = useState(false);

  // Use a ref to manage the exit timer identity
  const exitTimerRef = React.useRef<NodeJS.Timeout | null>(null);

  // Unified logic to update reading state based on current velocity
  const updateReadingState = React.useCallback((v: number) => {
    // Clear timer if we exceed skim entrance threshold
    if (v > VELOCITY_THRESHOLDS.SKIM_ENTER) {
      setReadingState("skim");
      if (exitTimerRef.current) {
        clearTimeout(exitTimerRef.current);
        exitTimerRef.current = null;
      }
    }
    // Start or continue exit timer if below exit threshold
    else if (v < VELOCITY_THRESHOLDS.SKIM_EXIT) {
      setReadingState((prev) => {
        if (prev === "skim" && !exitTimerRef.current) {
          exitTimerRef.current = setTimeout(() => {
            setReadingState("detailed");
            exitTimerRef.current = null;
          }, TIMINGS.SKIM_EXIT_DELAY);
        }
        return prev;
      });
    }
    // Intermediate zone: cancel exit timer if user speeds up slightly
    else if (
      v >= VELOCITY_THRESHOLDS.SKIM_EXIT &&
      v <= VELOCITY_THRESHOLDS.SKIM_ENTER &&
      exitTimerRef.current
    ) {
      clearTimeout(exitTimerRef.current);
      exitTimerRef.current = null;
    }
  }, []);

  // effectiveVelocity is either manual override or scroll velocity
  const velocity = manualVelocity !== null ? manualVelocity : scrollV;

  useEffect(() => {
    const unsubscribe = smoothVelocity.on("change", (v) => {
      if (isVelocityLocked) {
        return;
      }
      const absV = Math.floor(Math.abs(v));
      if (absV !== Math.floor(scrollV)) {
        setScrollV(absV);

        // Update reading state based on new scroll velocity (only if manual override is OFF)
        if (manualVelocity === null) {
          updateReadingState(absV);
        }
      }
    });

    return () => unsubscribe();
  }, [
    smoothVelocity,
    scrollV,
    isVelocityLocked,
    manualVelocity,
    updateReadingState,
  ]);

  const lockVelocity = React.useCallback(() => {
    setIsVelocityLocked(true);
    // Neutralize the underlying MotionValues to prevent the spring from "momentum-swallowing" the spike
    scrollVelocity.set(0);
    smoothVelocity.set(0);

    if (exitTimerRef.current) {
      clearTimeout(exitTimerRef.current);
      exitTimerRef.current = null;
    }

    // A slightly longer lock ensures the browser and framer-motion have fully settled
    setTimeout(
      () => setIsVelocityLocked(false),
      TIMINGS.SCROLL_LOCK_DURATION + 100
    );
  }, [scrollVelocity, smoothVelocity]);

  const handleSetManualVelocity = React.useCallback(
    (v: number | null) => {
      setManualVelocity(v);
      if (v !== null) {
        updateReadingState(v);
      }
    },
    [updateReadingState]
  );

  useEffect(() => {
    const unsubscribe = scrollY.on("change", (latest) => {
      if (latest <= 0) {
        updateReadingState(0);
      }
    });
    return () => unsubscribe();
  }, [scrollY, updateReadingState]);

  // Optimize derived values and context object
  const normalizedVelocity = React.useMemo(
    () => Math.min(velocity / VELOCITY_THRESHOLDS.NORMALIZATION_MAX, 1),
    [velocity]
  );

  const isScrolling = React.useMemo(
    () =>
      velocity > VELOCITY_THRESHOLDS.IS_SCROLLING || manualVelocity !== null,
    [velocity, manualVelocity]
  );

  const contextValue = React.useMemo(
    () => ({
      velocity,
      normalizedVelocity,
      readingState,
      isScrolling,
      manualVelocity,
      setManualVelocity: handleSetManualVelocity,
      lockVelocity,
    }),
    [
      velocity,
      normalizedVelocity,
      readingState,
      isScrolling,
      manualVelocity,
      handleSetManualVelocity,
      lockVelocity,
    ]
  );

  return (
    <VelocityContext.Provider value={contextValue}>
      {children}
    </VelocityContext.Provider>
  );
};

export const useVelocityState = () => {
  const context = useContext(VelocityContext);
  if (context === undefined) {
    throw new Error("useVelocityState must be used within a VelocityProvider");
  }
  return context;
};

"use client";

import { AlertCircle, ImageIcon } from "lucide-react";
import { AnimatePresence, motion } from "motion/react";
import type React from "react";
import { useState } from "react";
import { SPRING_CONFIGS } from "./constants";
import { useVelocityState } from "./VelocityContext";

interface VelocityImageProps {
  alt: string;
  src: string;
}

export const VelocityImage: React.FC<VelocityImageProps> = ({ src, alt }) => {
  const { normalizedVelocity, readingState } = useVelocityState();
  const [error, setError] = useState(false);
  const [loading, setLoading] = useState(true);

  const isSkim = readingState === "skim";

  const opacity = 0.8 + (1 - normalizedVelocity) * 0.2;

  return (
    <motion.div
      animate={{
        height: isSkim ? "auto" : 0,
        opacity: isSkim ? 1 : 0,
        marginBottom: isSkim ? 80 : 0,
        marginTop: isSkim ? 80 : 0,
        pointerEvents: isSkim ? "auto" : "none",
      }}
      className="relative w-full overflow-hidden px-4 sm:px-0"
      initial={false}
      layout="position"
      transition={SPRING_CONFIGS.IMAGE_TRANSITION}
    >
      <motion.div
        animate={{
          opacity,
          y: isSkim ? -normalizedVelocity * 20 : 0,
        }}
        className="relative z-10 flex aspect-video min-h-[200px] items-center justify-center overflow-hidden rounded-2xl border border-white/10 bg-zinc-900 shadow-[0_0_50px_rgba(0,0,0,0.5)] sm:min-h-[300px]"
        style={{
          transformOrigin: "center center",
        }}
        transition={SPRING_CONFIGS.IMAGE_MOTION}
      >
        <AnimatePresence mode="wait">
          {/* Only render image if we are skimming or transitioning */}
          {(isSkim || normalizedVelocity > 0.1) && !error ? (
            <motion.div
              animate={{ opacity: 1 }}
              className="relative h-full w-full"
              exit={{ opacity: 0 }}
              initial={{ opacity: 0 }}
              key="content"
            >
              {loading ? (
                <div className="absolute inset-0 flex items-center justify-center text-zinc-800">
                  <ImageIcon
                    className="animate-pulse"
                    size={48}
                    strokeWidth={1}
                  />
                </div>
              ) : null}
              <motion.img
                alt={alt}
                className="block h-full w-full object-cover"
                onError={() => setError(true)}
                onLoad={() => setLoading(false)}
                src={src}
                transition={{ duration: 0.5 }}
              />
            </motion.div>
          ) : null}

          {error ? (
            <motion.div
              animate={{ opacity: 1 }}
              className="flex flex-col items-center gap-2 text-zinc-600"
              initial={{ opacity: 0 }}
              key="error"
            >
              <AlertCircle size={40} strokeWidth={1} />
              <span className="font-mono text-xs uppercase tracking-widest">
                {alt} (Load Failed)
              </span>
            </motion.div>
          ) : null}
        </AnimatePresence>

        <motion.div
          animate={{
            background:
              isSkim && !error
                ? `linear-gradient(to bottom, rgba(0,0,0,${normalizedVelocity * 0.3}), transparent)`
                : "rgba(0,0,0,0)",
          }}
          className="pointer-events-none absolute inset-0"
        />

        {/* Subtle highlight instead of blur */}
        {normalizedVelocity > 0.4 && !error ? (
          <motion.div
            className="pointer-events-none absolute inset-0 bg-white/5 mix-blend-overlay"
            style={{
              opacity: (normalizedVelocity - 0.4) * 1.5,
            }}
          />
        ) : null}
      </motion.div>

      <motion.div
        animate={{
          opacity: isSkim && !error ? normalizedVelocity * 0.3 : 0,
        }}
        className="absolute inset-0 -z-10 rounded-full bg-primary/20 blur-[100px]"
      />
    </motion.div>
  );
};

"use client";

import { AnimatePresence, motion } from "motion/react";
import type React from "react";
import { SPRING_CONFIGS } from "./constants";
import { useVelocityState } from "./VelocityContext";

interface VelocityTextProps {
  detailed: string;
  summary: string;
}

export const VelocityText: React.FC<VelocityTextProps> = ({
  detailed,
  summary,
}) => {
  const { readingState, normalizedVelocity } = useVelocityState();
  const isSkim = readingState === "skim";

  // Removed blur entirely for maximum readability as requested
  const opacityValue = isSkim ? Math.max(0.9, 1 - normalizedVelocity * 0.1) : 1;

  return (
    <motion.div
      className="relative my-12 overflow-hidden font-sans"
      layout
      transition={SPRING_CONFIGS.TRANSITION}
    >
      <AnimatePresence initial={false} mode="popLayout">
        <motion.div
          animate={{
            opacity: opacityValue,
            y: 0,
          }}
          className={`${
            isSkim
              ? "font-black text-2xl text-white leading-tight tracking-tighter drop-shadow-[0_0_10px_rgba(255,255,255,0.4)] sm:text-4xl"
              : "font-serif text-lg text-zinc-400 leading-relaxed"
          } w-full`}
          exit={{ opacity: 0, y: isSkim ? -10 : 10 }}
          initial={{ opacity: 0, y: isSkim ? 10 : -10 }}
          key={readingState}
          transition={{
            duration: 0.3,
            ease: [0.16, 1, 0.3, 1],
          }}
        >
          {isSkim ? summary : detailed}
        </motion.div>
      </AnimatePresence>

      {/* Visual noise/streak effect during transition - kept very subtle */}
      {normalizedVelocity > 0.5 && !isSkim && (
        <motion.div
          animate={{ scaleX: 1, opacity: 0.3 }}
          className="absolute inset-x-0 top-1/2 h-[1px] bg-primary/20"
          initial={{ scaleX: 0, opacity: 0 }}
          style={{
            transformOrigin: "left",
          }}
        />
      )}
    </motion.div>
  );
};

